CREATE TABLE currencies (
    code CHAR(3) PRIMARY KEY,
    name VARCHAR(50) NOT NULL,
    exchange_rate DECIMAL(20, 8) DEFAULT 1,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(200));
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(200) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY (user_id, role_id));

CREATE TABLE categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(500), parent_id BIGINT, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE brands (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(120) NOT NULL UNIQUE, logo_url VARCHAR(500), description VARCHAR(1000), country VARCHAR(100), is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id BIGINT, brand_id BIGINT, name VARCHAR(200) NOT NULL, description VARCHAR(2000), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE product_variants (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL, sku VARCHAR(100) NOT NULL, name VARCHAR(200), attributes VARCHAR DEFAULT '{}', price DECIMAL(12, 2) NOT NULL, stock INTEGER DEFAULT 0, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMP WITH TIME ZONE);

CREATE TABLE addresses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, recipient_name VARCHAR(200) NOT NULL, phone VARCHAR(30) NOT NULL, line1 VARCHAR(500) NOT NULL, line2 VARCHAR(500), city VARCHAR(100) NOT NULL, postal_code VARCHAR(20), country_code CHAR(2) DEFAULT 'VN', is_default BOOLEAN DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE coupons (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, discount_type VARCHAR(20) NOT NULL, discount_value DECIMAL(12, 2) NOT NULL, max_uses INTEGER, used_count INTEGER DEFAULT 0, min_order_amount DECIMAL(12, 2) DEFAULT 0, starts_at TIMESTAMP WITH TIME ZONE NOT NULL, expires_at TIMESTAMP WITH TIME ZONE, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cart_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, variant_id BIGINT NOT NULL, quantity INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, shipping_address_id BIGINT, coupon_id BIGINT, subtotal DECIMAL(12,2) DEFAULT 0, discount_amount DECIMAL(12,2) DEFAULT 0, shipping_fee DECIMAL(12,2) DEFAULT 0, total DECIMAL(12,2) DEFAULT 0, currency CHAR(3) DEFAULT 'VND', status VARCHAR(30) DEFAULT 'pending', created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL, variant_id BIGINT, product_name VARCHAR(200) NOT NULL, variant_name VARCHAR(200), attributes VARCHAR, unit_price DECIMAL(12,2) NOT NULL, quantity INTEGER NOT NULL);
CREATE TABLE stock_movements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, variant_id BIGINT NOT NULL, change_amount INTEGER NOT NULL, reason VARCHAR(30) NOT NULL, reference_id BIGINT, note VARCHAR(500), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_media (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL, variant_id BIGINT, media_type VARCHAR(20) NOT NULL, url VARCHAR(500) NOT NULL, thumbnail_url VARCHAR(500), sort_order INTEGER DEFAULT 0, is_main BOOLEAN DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE coupon_redemptions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, coupon_id BIGINT NOT NULL, user_id BIGINT NOT NULL, order_id BIGINT NOT NULL, discount_amount DECIMAL(12,2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) DEFAULT 'VND', method VARCHAR(30) NOT NULL, status VARCHAR(30) DEFAULT 'pending', gateway_transaction_id VARCHAR(255), paid_at TIMESTAMP WITH TIME ZONE, refunded_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);

